import 'package:flutter/material.dart';

class OnboardingScreen extends StatefulWidget { const OnboardingScreen({super.key, required this.onDone}); final VoidCallback onDone; @override State<OnboardingScreen> createState()=>_OnboardingScreenState(); }
class _OnboardingScreenState extends State<OnboardingScreen>{final pages=const[('Scan any image',Icons.document_scanner_rounded,'Capture or share a document in seconds.'),('Extract text instantly',Icons.text_fields_rounded,'Edit, copy, save and share clean OCR text.'),('Ask AI about your images',Icons.auto_awesome_rounded,'Keep the image and OCR context together for smarter questions.')];int index=0;@override Widget build(BuildContext context){final p=pages[index];return Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(28),child:Column(children:[const Spacer(),Container(width:140,height:140,decoration:BoxDecoration(color:Color(0xFFE9EDFF),shape:BoxShape.circle),child:Icon(p.$2,size:68,color:Color(0xFF4967F5))),const SizedBox(height:44),Text(p.$1,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w900),textAlign:TextAlign.center),const SizedBox(height:12),Text(p.$3,textAlign:TextAlign.center,style:Theme.of(context).textTheme.bodyLarge),const Spacer(),Row(mainAxisAlignment:MainAxisAlignment.center,children:List.generate(pages.length,(i)=>AnimatedContainer(duration:const Duration(milliseconds:200),margin:const EdgeInsets.all(4),width:i==index?28:8,height:8,decoration:BoxDecoration(color:i==index?Theme.of(context).colorScheme.primary:Colors.black12,borderRadius:BorderRadius.circular(8))))),const SizedBox(height:24),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){if(index==pages.length-1){widget.onDone();}else{setState(()=>index++);}},child:Text(index==pages.length-1?'Get started':'Continue'))),TextButton(onPressed:widget.onDone,child:const Text('Skip'))]))));}}
